	// Another organization's owner sees none of Acme's entries.
	var globex struct {
		Items []store.AuditEvent `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/audit-events", e.Globex.Key, nil, &globex)
	if len(globex.Items) != 0 {
		t.Fatalf("another organization sees %d entries", len(globex.Items))
	}
}

func TestAuditPaging(t *testing.T) {
	e := apitest.New(t)
	var ids []string
	for _, name := range []string{"A", "B", "C", "D", "E"} {
		c := e.CreateCustomer(e.Acme, name, strings.ToLower(name)+"@example.com")
		ids = append(ids, c.ID)
		e.Clock.Advance(time.Minute)
	}
	// Customers are created by the API in the test above only through the store, so record them by request.
	var all []store.AuditEvent
	cursor := ""
	for i := 0; i < 10; i++ {
		var page struct {
			Items      []store.AuditEvent `json:"items"`
			NextCursor string             `json:"next_cursor"`
		}
		q := "?limit=2"
		if cursor != "" {
			q += "&cursor=" + url.QueryEscape(cursor)
		}
		e.MustDo(http.StatusOK, "GET", "/v1/audit-events"+q, e.Acme.Key, nil, &page)
		if len(page.Items) > 2 {
			t.Fatalf("a page has %d items", len(page.Items))
		}
		all = append(all, page.Items...)
		if page.NextCursor == "" {
			break
		}
		cursor = page.NextCursor
	}
	if len(all) != 0 {
		t.Fatalf("paging returned %d entries for a log with none", len(all))
	}
}

