73	func (s *Server) updatePlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
74		var in struct {
75			Name   *string `json:"name"`
76			Active *bool   `json:"active"`
77		}
78		if !decode(w, r, &in) {
79			return
80		}
81		var before store.Plan
82		pl, err := s.store.UpdatePlan(p.OrgID, r.PathValue("id"), func(pl *store.Plan) error {
83			before = *pl
84			if in.Name != nil {
85				pl.Name = *in.Name
86			}
87			if in.Active != nil {
88				pl.Active = *in.Active
89			}
90			return nil
91		})
92		if err != nil {
93			s.storeError(w, err)
94			return
95		}
96		s.audit(r, p, "plan.updated", store.AuditTarget{Type: "plan", ID: pl.ID}, diff(before, pl))
97		writeJSON(w, http.StatusOK, viewPlan(pl))
98	}
